12	
13	// Surface identifies a consumer-specific concrete model naming surface.
14	type Surface string
15	
16	const (
17		SurfaceAgentOpenAI    Surface = "agent.openai"
18		SurfaceAgentAnthropic Surface = "agent.anthropic"
19		SurfaceCodex          Surface = "codex"
20		SurfaceClaudeCode     Surface = "claude-code"
21		SurfaceGemini         Surface = "gemini"
22	)
23	
24	// ResolveOptions configures compatibility model-reference resolution.
25	type ResolveOptions struct {
26		Surface         Surface
27		AllowDeprecated bool
28	}
29	
30	// Catalog exposes the loaded v5 model catalog.
31	type Catalog struct {
32		manifest    manifest
33		manifestSrc string
34	}
35	
36	// Metadata describes the loaded manifest.
37	type Metadata struct {
38		ManifestSource  string
39		ManifestVersion int
40		CatalogVersion  string
41	}
42	
43	// Policy describes one canonical catalog routing policy.
44	type Policy struct {
45		Name       string
46		MinPower   int
47		MaxPower   int
48		AllowLocal bool
49		Require    []string
50	}
51	
52	// Provider describes one catalog-declared provider system.
53	type Provider struct {
54		Name             string
55		Type             string
56		IncludeByDefault bool
57		Billing          BillingModel
58	}
59	
60	// SurfacePolicy is kept as a narrow compatibility container for callers that
61	// have not yet moved reasoning defaults from surface projections to model entries.
62	type SurfacePolicy struct {
63		ReasoningDefault       reasoning.Reasoning
64		PlacementOrder         []string
65		MaxInputCostPerMTokUSD *float64
66		FailurePolicy          string
67	}
68	
69	// ResolvedTarget is the compatibility output for model-reference resolution.
70	// In v5 CanonicalID is either a policy name or canonical model ID; there is no
71	// catalog alias concept behind it.
72	type ResolvedTarget struct {
73		Ref                string
74		Profile            string
75		Family             string
76		CanonicalID        string
77		ConcreteModel      string
78		SurfacePolicy      SurfacePolicy
79		Deprecated         bool
80		Replacement        string
81		CatalogVersion     string
82		ManifestSource     string
83		ManifestVersion    int
84		CostInputPerM      float64
85		CostOutputPerM     float64
86		CostCacheReadPerM  float64
87		CostCacheWritePerM float64
88		ContextWindow      int
89		SWEBenchVerified   float64
90		LiveCodeBench      float64
91		BenchmarkAsOf      string
92		OpenRouterRefID    string
93	}
94	
95	// ModelEligibility describes whether a catalog model can participate in
96	// unpinned automatic routing or only explicit model pins.
97	type ModelEligibility struct {
98		Power        int
99		ExactPinOnly bool
100		AutoRoutable bool
101	}
102	
103	// Metadata returns the loaded manifest metadata for inspection surfaces.
104	func (c *Catalog) Metadata() Metadata {
105		return Metadata{
106			ManifestSource:  c.manifestSrc,
107			ManifestVersion: c.manifest.Version,
108			CatalogVersion:  c.manifest.CatalogVersion,
109		}
110	}
111	
112	// Policies returns all canonical policies in deterministic order.
113	func (c *Catalog) Policies() []Policy {
114		names := make([]string, 0, len(c.manifest.Policies))
115		for name := range c.manifest.Policies {
116			names = append(names, name)
117		}
118		sort.Strings(names)
119		out := make([]Policy, 0, len(names))
120		for _, name := range names {
121			policy, _ := c.Policy(name)
122			out = append(out, policy)
123		}
124		return out
125	}
126	
127	// Policy returns one canonical policy definition.
128	func (c *Catalog) Policy(name string) (Policy, bool) {
129		name = strings.TrimSpace(name)
130		entry, ok := c.manifest.Policies[name]
131		if !ok {
132			return Policy{}, false
133		}
134		return Policy{
135			Name:       name,
136			MinPower:   entry.MinPower,
137			MaxPower:   entry.MaxPower,
138			AllowLocal: entry.AllowLocal,
139			Require:    append([]string(nil), entry.Require...),
140		}, true
141	}
142	
143	// Providers returns all catalog-declared provider systems in deterministic order.
144	func (c *Catalog) Providers() []Provider {
145		names := make([]string, 0, len(c.manifest.Providers))
146		for name := range c.manifest.Providers {
147			names = append(names, name)
148		}
149		sort.Strings(names)
150		out := make([]Provider, 0, len(names))
151		for _, name := range names {
152			entry := c.manifest.Providers[name]
153			billing := BillingModel(entry.Billing)
154			if billing == BillingModelUnknown {
155				billing = BillingForProviderSystem(entry.Type)
156				if billing == BillingModelUnknown {
157					billing = BillingForHarness(entry.Type)
158				}
159			}
160			out = append(out, Provider{
161				Name:             name,
162				Type:             entry.Type,
163				IncludeByDefault: entry.IncludeByDefault,
164				Billing:          billing,
165			})
166		}
167		return out
168	}
169	
170	// UnknownReferenceError indicates that a reference is not known to the catalog.
171	type UnknownReferenceError struct {
172		Ref string
173	}
174	
175	func (e *UnknownReferenceError) Error() string {
176		return fmt.Sprintf("modelcatalog: unknown reference %q", e.Ref)
177	}
178	
179	// MissingSurfaceError indicates that a model cannot be projected to the requested surface.
180	type MissingSurfaceError struct {
181		CanonicalID string
182		Surface     Surface
183	}
184	
185	func (e *MissingSurfaceError) Error() string {
186		return fmt.Sprintf("modelcatalog: reference %q has no mapping for surface %q", e.CanonicalID, e.Surface)
187	}
188	
189	// DeprecatedTargetError indicates that a deprecated or stale model was resolved in strict mode.
190	type DeprecatedTargetError struct {
191		CanonicalID       string
192		Status            string
193		Replacement       string
194		SuggestedProfile  string
195		SuggestedMinPower int
196		SuggestedMaxPower int
197	}
198	
199	func (e *DeprecatedTargetError) Error() string {
200		if e.Replacement == "" {
