463	func (c *Catalog) LookupModel(id string) (ModelEntry, bool) {
464		if entry, ok := c.manifest.Models[id]; ok {
465			return entry, true
466		}
467		for _, entry := range c.manifest.Models {
468			for _, concrete := range entry.Surfaces {
469				if concrete == id {
470					return entry, true
471				}
472			}
