480	// ModelEligibility returns power and automatic-routing eligibility for a
481	// catalog model ID or any declared provider surface ID. Unknown models return
482	// ok=false; known models with missing/zero power remain exact-pin-capable but
483	// are not auto-routable.
484	func (c *Catalog) ModelEligibility(id string) (ModelEligibility, bool) {
485		entry, ok := c.LookupModel(id)
486		if !ok {
487			for modelID, candidate := range c.manifest.Models {
488				if strings.EqualFold(modelID, id) {
489					entry = candidate
490					ok = true
491					break
492				}
493				for _, surfaceID := range candidate.Surfaces {
494					if strings.EqualFold(surfaceID, id) {
495						entry = candidate
496						ok = true
497						break
498					}
499				}
500				if ok {
501					break
502				}
503			}
504			if !ok {
505				return ModelEligibility{}, false
506			}
507		}
508		return ModelEligibility{
509			Power:        entry.Power,
510			ExactPinOnly: entry.ExactPinOnly,
511			AutoRoutable: entry.AutoRoutable(),
512		}, true
513	}
