515	// ContextWindowForModel returns the context window in tokens for the given
516	// concrete model ID, or 0 if the model is not in the catalog or has no
517	// context_window declared. Used as a fallback when the provider's live API
518	// does not expose its context window (e.g. LM Studio's /v1/models omits it).
519	// Matching is case-insensitive to accept both "qwen3.5-27b" and "Qwen3.5-27B".
520	func (c *Catalog) ContextWindowForModel(id string) int {
521		if entry, ok := c.LookupModel(id); ok && entry.ContextWindow > 0 {
522			return entry.ContextWindow
523		}
524		best := 0
525		id = strings.TrimSpace(id)
526		if id == "" {
527			return 0
528		}
529		for modelID, entry := range c.manifest.Models {
530			if strings.EqualFold(modelID, id) || sameModelVariant(id, modelID) {
531				if entry.ContextWindow > best {
532					best = entry.ContextWindow
533				}
534			}
535			for _, concrete := range entry.Surfaces {
536				if strings.EqualFold(concrete, id) || sameModelVariant(id, concrete) {
537					if entry.ContextWindow > best {
538						best = entry.ContextWindow
539					}
540				}
541			}
542		}
543		if best > 0 {
544			return best
545		}
546		return 0
547	}
