549	// SupportsToolsForModel reports whether the given concrete model ID supports
550	// tool/function calling per the catalog. Returns true when the model is not
551	// in the catalog (caller assumes capable by default) and false only when the
552	// catalog explicitly marks the model with no_tools=true. Matching is
553	// case-insensitive to mirror ContextWindowForModel.
554	func (c *Catalog) SupportsToolsForModel(id string) bool {
555		if c == nil {
556			return true
557		}
558		if entry, ok := c.LookupModel(id); ok {
559			return !entry.NoTools
560		}
561		return true
562	}
