564	func (c *Catalog) lookupModelVariant(id string) (string, ModelEntry, bool) {
565		id = strings.TrimSpace(id)
566		if id == "" {
567			return "", ModelEntry{}, false
568		}
569		var (
570			best     ModelEntry
571			bestID   string
572			bestSeen bool
573		)
574		for modelID, entry := range c.manifest.Models {
575			matched := sameModelVariant(id, modelID)
576			if !matched {
577				for _, surfaceID := range entry.Surfaces {
578					if sameModelVariant(id, surfaceID) {
579						matched = true
580						break
581					}
582				}
583			}
584			if !matched {
585				continue
586			}
587			if !bestSeen || betterModelVariantMatch(entry, modelID, best, bestID) {
588				best = entry
589				bestID = modelID
590				bestSeen = true
591			}
592		}
593		if !bestSeen {
594			return "", ModelEntry{}, false
595		}
596		return bestID, best, true
597	}
598	
599	func betterModelVariantMatch(candidate ModelEntry, candidateID string, best ModelEntry, bestID string) bool {
600		candidateStatus := normalizedStatus(candidate.Status)
601		bestStatus := normalizedStatus(best.Status)
602		if candidateStatus != bestStatus {
603			return statusRank(candidateStatus) > statusRank(bestStatus)
604		}
605		if candidate.Power != best.Power {
606			return candidate.Power > best.Power
607		}
608		if candidate.ContextWindow != best.ContextWindow {
609			return candidate.ContextWindow > best.ContextWindow
610		}
611		if candidate.ExactPinOnly != best.ExactPinOnly {
612			return !candidate.ExactPinOnly && best.ExactPinOnly
613		}
614		return candidateID < bestID
615	}
616	
617	func statusRank(status string) int {
618		switch normalizedStatus(status) {
619		case statusActive:
620			return 2
621		case statusDeprecated:
622			return 1
623		case statusStale:
624			return 0
625		default:
626			return -1
627		}
628	}
629	
630	func sameModelVariant(a, b string) bool {
631		ca := catalogModelKey(a)
632		cb := catalogModelKey(b)
633		if ca == "" || cb == "" {
634			return false
635		}
636		if ca == cb {
637			return true
638		}
639		if sameNamedFamilyMajor(a, b) {
640			return true
641		}
642		if len(ca) < 8 || len(cb) < 8 {
643			return false
644		}
645		return strings.Contains(ca, cb) || strings.Contains(cb, ca)
646	}
647	
648	func catalogModelKey(s string) string {
649		s = strings.TrimSpace(s)
650		if slash := strings.Index(s, "/"); slash > 0 {
651			s = s[slash+1:]
652		}
653		s = strings.ToLower(s)
654		var b strings.Builder
655		b.Grow(len(s))
656		for _, r := range s {
657			switch {
658			case r >= 'a' && r <= 'z':
659				b.WriteRune(r)
660			case r >= '0' && r <= '9':
661				b.WriteRune(r)
662			}
663		}
664		return b.String()
665	}
666	
667	func sameNamedFamilyMajor(a, b string) bool {
668		familyA, majorA := namedFamilyMajor(a)
669		familyB, majorB := namedFamilyMajor(b)
670		return familyA != "" && familyA == familyB && majorA > 0 && majorA == majorB
671	}
672	
673	func namedFamilyMajor(s string) (string, int) {
674		tokens := catalogModelTokens(s)
675		if len(tokens) == 0 {
676			return "", 0
677		}
678		family := ""
679		for _, token := range tokens {
680			switch token {
681			case "opus", "sonnet", "haiku":
682				family = token
683			}
684		}
685		if family == "" {
686			return "", 0
687		}
688		for _, token := range tokens {
689			n, err := strconv.Atoi(token)
690			if err == nil {
691				return family, n
692			}
693		}
694		return family, 0
695	}
696	
697	func catalogModelTokens(s string) []string {
698		s = strings.TrimSpace(s)
699		if slash := strings.Index(s, "/"); slash > 0 {
700			s = s[slash+1:]
701		}
702		s = strings.ToLower(s)
703		var out []string
704		var b strings.Builder
705		flush := func() {
706			if b.Len() == 0 {
707				return
708			}
709			out = append(out, b.String())
710			b.Reset()
711		}
712		for _, r := range s {
713			switch {
714			case r >= 'a' && r <= 'z':
715				b.WriteRune(r)
716			case r >= '0' && r <= '9':
717				b.WriteRune(r)
718			default:
719				flush()
720			}
721		}
722		flush()
723		return out
724	}
