746	// PricingFor returns pricing for all active concrete models across all surfaces.
747	func (c *Catalog) PricingFor() map[string]CatalogModelPricing {
748		result := make(map[string]CatalogModelPricing)
749		for modelID, entry := range c.manifest.Models {
750			input := entry.inputCostPerM()
751			if input <= 0 {
752				continue
753			}
754			result[modelID] = CatalogModelPricing{
755				InputPerMTok:   input,
756				OutputPerMTok:  entry.outputCostPerM(),
757				CacheReadPerM:  entry.CostCacheReadPerM,
758				CacheWritePerM: entry.CostCacheWritePerM,
759			}
760		}
761		return result
762	}
