117	func SubprocessHarnessModelIDs(name string, cfg harnesses.HarnessConfig) []string {
118		mdh, ok := builtin.New(name).(harnesses.ModelDiscoveryHarness)
119		if !ok {
120			return nil
121		}
122		payload, ok := cachedSubprocessDiscovery(name, mdh)
123		if !ok {
124			// Model discovery failed; return no models rather than a fallback.
125			// This enforces the no-static-fallback principle.
126			return nil
127		}
128		snapshot := payload.snapshot()
129		var models []string
130		models = AppendUniqueModelIDs(models, snapshot.Models...)
131		for _, family := range mdh.SupportedAliases() {
132			resolved, err := mdh.ResolveModelAlias(family, snapshot)
133			if err == nil && resolved != family {
134				models = AppendUniqueModelIDs(models, resolved)
135			}
136		}
137		return models
138	}
