16	// View captures the routing-relevant metadata derived from a model catalog
17	// entry and the live/provider snapshot state around it.
18	type View struct {
19		Power           int
20		ExactPinOnly    bool
21		AutoRoutable    bool
22		ExclusionReason string
23	}
24	
25	// Resolve computes the routing-relevant view for a model ID. includeByDefault
26	// is the provider-level include flag from the assembled snapshot.
27	func Resolve(modelID string, includeByDefault bool, status string, cat *modelcatalog.Catalog) View {
28		var out View
29		var catalogAuto bool
30	
31		if cat != nil {
32			if entry, ok := cat.LookupModel(modelID); ok {
33				out.Power = entry.Power
34				if eligibility, ok := cat.ModelEligibility(modelID); ok {
35					out.ExactPinOnly = eligibility.ExactPinOnly
36					catalogAuto = eligibility.AutoRoutable
37				}
38			}
39		}
40	
41		if !catalogAuto {
42			if out.Power == 0 {
43				out.ExclusionReason = exclusionCatalogUnknown
44			} else {
45				out.ExclusionReason = exclusionCatalogNotRoutable
46			}
47		}
48		if catalogAuto && !includeByDefault {
49			out.ExclusionReason = exclusionProviderExcluded
50		}
51		if catalogAuto && includeByDefault && !statusAllowsRouting(status) {
52			out.ExclusionReason = exclusionStatusUnavailable
53		}
54	
55		out.AutoRoutable = catalogAuto && includeByDefault && statusAllowsRouting(status)
56		return out
57	}
58	
59	func statusAllowsRouting(status string) bool {
60		switch strings.TrimSpace(status) {
61		case "", "available", "rate_limited":
62			return true
63		default:
64			return status != "unknown" && status != "unreachable"
65		}
66	}
