173	func ClaudeCLIExecutableModel(model string) string {
174		normalized := strings.ToLower(strings.TrimSpace(model))
175		switch {
176		case normalized == "sonnet" || strings.HasPrefix(normalized, "sonnet-") || strings.HasPrefix(normalized, "claude-sonnet-"):
177			return "sonnet"
178		case normalized == "opus" || strings.HasPrefix(normalized, "opus-") || strings.HasPrefix(normalized, "claude-opus-"):
179			return "opus"
180		case normalized == "haiku" || strings.HasPrefix(normalized, "haiku-") || strings.HasPrefix(normalized, "claude-haiku-"):
181			return "haiku"
182		default:
183			return model
184		}
185	}
